        .ios-bounce {
            animation: iosBounce 0.3s ease-out;
        }
        @keyframes iosBounce {
            0% { transform: scale(1); }
            50% { transform: scale(0.95); }
            100% { transform: scale(1); }
        }
        .touch-feedback {
            position: relative;
            overflow: hidden;
        }
        .touch-feedback::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            background: rgba(255, 255, 255, 0.3);
            border-radius: 50%;
            transform: translate(-50%, -50%);
            transition: width 0.3s ease, height 0.3s ease;
            pointer-events: none;
        }
        .touch-feedback.active::before {
            width: 200px;
            height: 200px;
        }
        .swipe-indicator {
            position: fixed;
            top: 50%;
            left: 10px;
            transform: translateY(-50%);
            width: 4px;
            height: 60px;
